import{_ as o,C as i,o as r,c as n,a2 as a,E as s}from"./chunks/framework.CBxkvBm_.js";const b=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),l={name:"guide/introduction.md"};function c(d,e,m,p,h,u){const t=i("MermaidBlock");return r(),n("div",null,[e[0]||(e[0]=a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Welcome to <strong>ModelScript</strong>, the open-source <strong>computable digital thread</strong> platform and polyglot compiler designed for modern multi-domain engineering.</p><hr><h2 id="what-is-the-computable-digital-thread" tabindex="-1">What is the Computable Digital Thread? <a class="header-anchor" href="#what-is-the-computable-digital-thread" aria-label="Permalink to &quot;What is the Computable Digital Thread?&quot;">​</a></h2><p>Modern complex systems — from electric vehicles and aerospace systems to industrial robotics — require seamless coordination across disparate engineering domains:</p><ul><li><strong>System Architecture &amp; Requirements</strong> (SysML v2, KerML, ReqIF)</li><li><strong>1D Multi-Domain Physical Simulation</strong> (Modelica 3.x, SSP)</li><li><strong>3D CAD Geometry &amp; Envelopes</strong> (STEP ISO 10303, OpenSCAD CSG)</li><li><strong>Continuum Field Physics</strong> (FEA structural stress, CFD aerodynamics)</li><li><strong>Ontological Taxonomies &amp; Rules</strong> (OWL2 Functional Syntax)</li></ul><p>Traditionally, these disciplines operate in disconnected silos. Enterprise &quot;digital threads&quot; have historically been <strong>passive and descriptive</strong> — composed of static document links, slow PLM databases, and manual spreadsheets that fall out of sync the moment a parameter changes.</p><p><strong>ModelScript makes the digital thread <em>computable</em>.</strong></p><p>Instead of passive hyperlinks, ModelScript treats engineering models as <strong>executable, code-first specifications</strong> evaluated continuously by native WebAssembly compilers, graph rewriting engines, and formal solvers:</p>',9)),s(t,{code:"flowchart%20LR%0A%20%20%20%20A%5B%22Requirements%3Cbr%2F%3E(SysML%20v2%20%2F%20ReqIF)%22%5D%20%3C--%3E%7C%22TGG%20Rewriting%22%7C%20P%5B%221D%20Dynamics%3Cbr%2F%3E(Modelica)%22%5D%0A%20%20%20%20P%20%3C--%3E%7C%22DynamicSelect%22%7C%20G%5B%223D%20CAD%20Geometry%3Cbr%2F%3E(STEP%20%2F%20CSG)%22%5D%0A%20%20%20%20P%20%3C--%3E%7C%22Field%20Coupling%22%7C%20C%5B%22Continuum%20Analysis%3Cbr%2F%3E(FEA%20%2F%20CFD)%22%5D%0A%20%20%20%20A%20%26%20P%20%26%20G%20%26%20C%20--%3E%7C%22Nelson-Oppen%20Coordinator%22%7C%20V%5B%22Cryptographic%20Proof%20Manifest%3Cbr%2F%3E%26%20Continuous%20Verification%22%5D%0A"}),e[1]||(e[1]=a('<hr><h2 id="core-pillars-of-modelscript" tabindex="-1">Core Pillars of ModelScript <a class="header-anchor" href="#core-pillars-of-modelscript" aria-label="Permalink to &quot;Core Pillars of ModelScript&quot;">​</a></h2><h3 id="_1-code-first-engineering-models" tabindex="-1">1. Code-First Engineering Models <a class="header-anchor" href="#_1-code-first-engineering-models" aria-label="Permalink to &quot;1. Code-First Engineering Models&quot;">​</a></h3><p>Every artifact lives as clean, text-based code versioned in Git. Say goodbye to proprietary binary files and monolithic GUI databases. Diff, review, merge, and test engineering models using standard modern developer workflows and CI/CD pipelines.</p><h3 id="_2-high-performance-webassembly-cst-dae-arenas" tabindex="-1">2. High-Performance WebAssembly CST &amp; DAE Arenas <a class="header-anchor" href="#_2-high-performance-webassembly-cst-dae-arenas" aria-label="Permalink to &quot;2. High-Performance WebAssembly CST &amp; DAE Arenas&quot;">​</a></h3><p>Powered by ahead-of-time generated WebAssembly GLR incremental parsers and a zero-allocation Struct-of-Arrays (SoA) linear memory architecture (<code>DAEBuilder</code>). Hierarchical models flatten into Differential Algebraic Equations with zero garbage collection pause, enabling microsecond cycle times inside IDEs and web browsers.</p><h3 id="_3-bidirectional-triple-graph-grammars-tgg" tabindex="-1">3. Bidirectional Triple Graph Grammars (TGG) <a class="header-anchor" href="#_3-bidirectional-triple-graph-grammars-tgg" aria-label="Permalink to &quot;3. Bidirectional Triple Graph Grammars (TGG)&quot;">​</a></h3><p>Keep architecture and physics in permanent alignment. Declarative TGG rules compile into AOT WebAssembly dispatch tables that automatically propagate architectural changes (SysML v2) forward into physical simulation models (Modelica), while back-annotating numerical simulation sizing results back into architectural specifications.</p><h3 id="_4-nelson-oppen-multi-theory-formal-verification" tabindex="-1">4. Nelson-Oppen Multi-Theory Formal Verification <a class="header-anchor" href="#_4-nelson-oppen-multi-theory-formal-verification" aria-label="Permalink to &quot;4. Nelson-Oppen Multi-Theory Formal Verification&quot;">​</a></h3><p>Cross-domain verification is solved through an extensible Nelson-Oppen theory coordinator. Exchange equality facts and conflict clauses across six signature-disjoint theory oracles — Ontology (OWL2), Interval Constraints, Abstract Interpretation, Continuous Reachability (Zonotopes), Dynamic DAE Simulation, and 3D Spatial CAD clearance.</p><h3 id="_5-multi-language-language-server-protocol-lsp" tabindex="-1">5. Multi-Language Language Server Protocol (LSP) <a class="header-anchor" href="#_5-multi-language-language-server-protocol-lsp" aria-label="Permalink to &quot;5. Multi-Language Language Server Protocol (LSP)&quot;">​</a></h3><p>A unified background worker indexing mixed-language workspaces simultaneously. Enjoy instant go-to-definition, hover documentation, semantic completion, and real-time compiler diagnostics across Modelica, SysML v2, STEP, and OWL2 in VS Code or browser environments.</p><hr><h2 id="ready-to-get-started" tabindex="-1">Ready to Get Started? <a class="header-anchor" href="#ready-to-get-started" aria-label="Permalink to &quot;Ready to Get Started?&quot;">​</a></h2><p>Proceed to the <a href="./installation.html">Installation guide</a> to set up the <code>msx</code> CLI and VS Code extension, or follow <a href="./getting-started.html">Getting Started</a> to build your first connected model.</p>',15))])}const f=o(l,[["render",c]]);export{b as __pageData,f as default};
